const RESPONSE_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['notes', 'concerns'],
  properties: {
    notes: {
      type: 'array',
      items: {
        type: 'object', additionalProperties: false, required: ['sn', 'note'],
        properties: { sn: { type: 'string' }, note: { type: 'string' } },
      },
    },
    concerns: {
      type: 'array',
      items: {
        type: 'object', additionalProperties: false, required: ['description', 'rows'],
        properties: { description: { type: 'string' }, rows: { type: 'array', items: { type: 'integer' } } },
      },
    },
  },
};

// Rows named by a check come first, then the largest entries for context.
function rowsForSection(section, transactions) {
  const named = new Set(section.items.flatMap((i) => i.rows));
  const size = (t) => Math.abs(t.credit) + Math.abs(t.debit);
  const flagged = transactions.filter((t) => named.has(t.row));
  const largest = transactions.filter((t) => !named.has(t.row)).sort((a, b) => size(b) - size(a));
  return [...flagged, ...largest]
    .slice(0, MAX_ROWS_PER_SECTION)
    .map(({ row, date, description, debit, credit, balance }) => ({ row, date, description, debit, credit, balance }));
}

function buildRequest({ model, section, transactions, faults, earlier }) {
  const content = {
    section: section.name,
    // E003 is about another submission, so its remarks are not sent.
    results: section.items.map(({ sn, parameter, rule, status, severity, remarks }) =>
      ({ sn, parameter, rule, status, severity, remarks: sn === 'E003' ? undefined : remarks })),
    faults: section.key === 'B' ? faults.slice(0, 20) : undefined,
    firstReview: earlier,
    transactions: rowsForSection(section, transactions),
  };
  const request = {
    model,
    max_tokens: MAX_TOKENS,
    system: SYSTEM_PROMPT,
    output_config: { effort: 'low', format: { type: 'json_schema', schema: RESPONSE_SCHEMA } },
    messages: [{ role: 'user', content: JSON.stringify(content) }],
  };
  // If a safety classifier declines, the API may retry on another Claude model.
  // The model that actually answered is recorded in the response and the log.
  if (model !== MODELS.triage) request.fallbacks = 'default';
  return request;
}

function buildTriageRequests({ sections, transactions, faults }) {
  return sections.map((section) => ({
    sectionKey: section.key,
    request: buildRequest({ model: MODELS.triage, section, transactions, faults }),
  }));
}

// Reads one Messages API reply. Anything incomplete counts as a failure, so a
// failed review is never mistaken for "no concerns".
function readReply(reply) {
  const failed = (why) => ({ ok: false, why });
  if (!reply || reply.error || !Array.isArray(reply.content)) {
    return failed(String(reply?.error?.message || reply?.error || 'No reply').slice(0, 200));
  }
  if (reply.stop_reason !== 'end_turn') return failed(`Stopped early: ${reply.stop_reason}`);
  const text = reply.content.filter((b) => b && b.type === 'text').map((b) => b.text).join('');
  try {
    const parsed = JSON.parse(text);
    if (!Array.isArray(parsed.notes) || !Array.isArray(parsed.concerns)) return failed('Unexpected reply shape');
    return { ok: true, notes: parsed.notes, concerns: parsed.concerns };
  } catch (error) {
    return failed('Reply was not valid JSON');
  }
}

function summariseStage(stage, model, keys, replies) {
  const tokens = (field) => replies.reduce((total, r) => total + (r?.usage?.[field] || 0), 0);
  const cost = replies.reduce((total, r) => {
    const price = PRICES[r?.model] || PRICES[model];
    return total + ((r?.usage?.input_tokens || 0) * price[0] + (r?.usage?.output_tokens || 0) * price[1]) / 1e6;
  }, 0);
  const results = keys.map((key, i) => ({ key, ...readReply(replies[i]) }));
  return {
    results,
    log: {
      stage,
      requestedModel: model,
      servedModels: [...new Set(replies.map((r) => r?.model).filter(Boolean))],
      sections: keys,
      failed: results.filter((r) => !r.ok).map((r) => ({ section: r.key, why: r.why })),
      inputTokens: tokens('input_tokens'),
      outputTokens: tokens('output_tokens'),
      estimatedCostUsd: Math.round(cost * 1e6) / 1e6,
    },
  };
}

// Decides whether stage 2 is needed, with which model, and for which sections.
function chooseRoute({ sections, verdict, faultCount, unmatchedSummary, triage }) {
  const serious = sections
    .filter((s) => s.items.some((i) => i.severity === 'HIGH' || i.severity === 'MEDIUM'))
    .map((s) => s.key);
  const failed = triage.results.filter((r) => !r.ok).map((r) => r.key);
  const doubted = triage.results.filter((r) => r.ok && r.concerns.length).map((r) => r.key);
  const escalate = [...new Set([...serious, ...failed, ...doubted])].sort();

  const complexReasons = [];
  if (faultCount >= COMPLEX_FAULT_COUNT) complexReasons.push(`${faultCount} balance faults`);
  if (unmatchedSummary) complexReasons.push('printed summary figures cannot be explained');
  if (verdict === 'INCONCLUSIVE') complexReasons.push('the statement could not be read reliably');

  if (complexReasons.length) {
    const keys = escalate.length ? escalate : sections.map((s) => s.key);
    return { tier: 'ESCALATED_OPUS', model: MODELS.complex, sections: keys, reasons: complexReasons };
  }
  const reasons = [];
  if (serious.length) reasons.push(`high or medium severity discrepancy in section(s) ${serious.join(', ')}`);
  if (doubted.length) reasons.push(`Haiku raised concerns in section(s) ${doubted.join(', ')}`);
  if (failed.length) reasons.push(`Haiku gave no usable answer for section(s) ${failed.join(', ')}`);
  if (escalate.length) return { tier: 'ESCALATED_SONNET', model: MODELS.standard, sections: escalate, reasons };
  return { tier: 'HAIKU_ONLY', model: null, sections: [], reasons: ['no serious discrepancy and no concern from Haiku'] };
}

function routeAfterTriage({ sections, transactions, faults, verdict, faultCount, unmatchedSummary, triageKeys, triageReplies }) {
  const triage = summariseStage(1, MODELS.triage, triageKeys, triageReplies);
  const route = chooseRoute({ sections, verdict, faultCount, unmatchedSummary, triage });
  const requests = route.sections.map((key) => {
    const first = triage.results.find((r) => r.key === key);
    return {
      sectionKey: key,
      request: buildRequest({
        model: route.model,
        section: sections.find((s) => s.key === key),
        transactions,
        faults,
        earlier: first && first.ok ? { notes: first.notes, concerns: first.concerns } : undefined,
      }),
    };
  });
  return { route, triage, requests };
}

// For an escalated section the stronger model's answer replaces Haiku's. If the
// stronger model fails, Haiku's answer is kept and the failure is reported.
function mergeAiReview({ sections, route, triage, escalationReplies = [] }) {
  const second = route.model ? summariseStage(2, route.model, route.sections, escalationReplies) : null;
  const notes = new Map();
  const concerns = [];
  const failedSections = [];

  for (const section of sections) {
    const first = triage.results.find((r) => r.key === section.key);
    const strong = second?.results.find((r) => r.key === section.key);
    const used = strong?.ok ? { ...strong, model: route.model } : first?.ok ? { ...first, model: MODELS.triage } : null;
    if ((strong && !strong.ok) || !used) failedSections.push(section.key);
    if (!used) continue;
    const known = new Set(section.items.map((i) => i.sn));
    for (const n of used.notes) {
      if (known.has(n?.sn) && typeof n.note === 'string') notes.set(n.sn, { model: used.model, text: n.note.slice(0, 500) });
    }
    for (const c of used.concerns) {
      if (typeof c?.description !== 'string') continue;
      concerns.push({
        section: section.key,
        model: used.model,
        description: c.description.slice(0, 500),
        rows: Array.isArray(c.rows) ? c.rows.filter(Number.isInteger).slice(0, 25) : [],
      });
    }
  }

  const stages = [triage.log, ...(second ? [second.log] : [])];
  const answered = stages.reduce((total, s) => total + s.sections.length - s.failed.length, 0);
  let status = 'COMPLETED';
  if (!answered) status = 'UNAVAILABLE';
  else if (failedSections.length) status = 'PARTIAL';

  const add = (field) => stages.reduce((total, s) => total + s[field], 0);
  return {
    sections: sections.map((s) => ({
      ...s,
      items: s.items.map((i) => (notes.has(i.sn) ? { ...i, aiNote: notes.get(i.sn) } : i)),
    })),
    aiReview: {
      requested: true,
      status,
      routing: { tier: route.tier, reasons: route.reasons, stages },
      concerns,
      failedSections,
      usage: {
        inputTokens: add('inputTokens'),
        outputTokens: add('outputTokens'),
        estimatedCostUsd: Math.round(add('estimatedCostUsd') * 1e6) / 1e6,
      },
    },
  };
}

// --- node ---
const data = $('Run Checklist').first(0).json;
const { route, triage } = $('Route Models').first(0).json;
const escalationReplies = $('Ask Escalation Model').isExecuted && route.model
  ? $('Ask Escalation Model').all().map((i) => i.json) : [];
const merged = mergeAiReview({ sections: data.sections, route, triage, escalationReplies });
merged.aiReview.durationMs = Date.now() - Date.parse($('Build Haiku Requests').first(0).json.aiStartedAt);
return [{ json: merged }];

/**
 * n8n node  : Assemble Response
 * Author    : Hasan Gaffar
 * Project   : n8n Bank Statement Verifier
 * Input from: AI Review Requested?, Merge AI Review
 * Output to : Prepare Audit Record, Build Error Response
 * Source    : generated from src/ by scripts/build-workflows.js
 */
// Shared helpers. The build script prepends this file to Code nodes that need it.

const round2 = (n) => Math.round((n + Number.EPSILON) * 100) / 100;
const sum = (values) => values.reduce((total, v) => total + v, 0);
const mean = (values) => (values.length ? sum(values) / values.length : 0);

const median = (values) => {
  if (!values.length) return 0;
  const sorted = [...values].sort((a, b) => a - b);
  const mid = Math.floor(sorted.length / 2);
  return sorted.length % 2 ? sorted[mid] : (sorted[mid - 1] + sorted[mid]) / 2;
};

const stdDev = (values) => {
  if (values.length < 2) return 0;
  const avg = mean(values);
  return Math.sqrt(mean(values.map((v) => (v - avg) ** 2)));
};

// Dates are handled as 'YYYY-MM-DD' strings and UTC day numbers, so the
// server timezone can never shift a transaction into another day.
const toDay = (iso) => Math.round(Date.parse(`${iso}T00:00:00Z`) / 86400000);
const fromDay = (day) => new Date(day * 86400000).toISOString().slice(0, 10);

const AVG_DAYS_PER_MONTH = 30.4375;

const formatMoney = (n) =>
  Number(n).toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

// The core of the project: is the arithmetic of the statement correct, and if
// not, where is it wrong and what is the likely cause?

const TOLERANCE = 0.01;
const same = (a, b) => Math.abs(a - b) <= TOLERANCE + 1e-9;

// `difference` is what the statement shows minus what the arithmetic gives.
function diagnose(transactions, index, difference, nextDifference) {
  const tx = transactions[index];
  const previous = transactions[index - 1];
  const money = formatMoney(Math.abs(difference));

  if (nextDifference !== null && same(difference, -nextDifference)) {
    return {
      cause: 'WRONG_BALANCE_FIGURE',
      explanation:
        `The balance printed on this row is off by ${money}. The following row continues correctly ` +
        'from the calculated value, so the balance figure itself was probably altered or mistyped.',
    };
  }
  if (
    previous &&
    previous.date === tx.date &&
    previous.description === tx.description &&
    previous.debit === tx.debit &&
    previous.credit === tx.credit &&
    same(previous.balance, tx.balance)
  ) {
    return {
      cause: 'DUPLICATED_LINE',
      explanation: 'This line repeats the previous one, including its balance. It was probably copied twice.',
    };
  }
  if ((tx.debit !== 0 && same(difference, 2 * tx.debit)) || (tx.credit !== 0 && same(difference, -2 * tx.credit))) {
    return {
      cause: 'DEBIT_CREDIT_SWAPPED',
      explanation:
        `The error is exactly twice the amount, so this ${tx.debit !== 0 ? 'debit was applied as a credit' : 'credit was applied as a debit'} ` +
        '(wrong column or wrong sign).',
    };
  }
  const direction = difference > 0 ? 'credit' : 'debit';
  return {
    cause: 'WRONG_AMOUNT_OR_MISSING_ENTRY',
    explanation:
      `Either the amount on this row is wrong by ${money}, or a ${direction} of ${money} is missing just before it.`,
  };
}

function checkRunningBalance(transactions, openingBalance) {
  const differences = transactions.map((tx, i) => {
    const previous = i === 0 ? openingBalance : transactions[i - 1].balance;
    if (previous === null || previous === undefined) return null;
    const expected = round2(previous + tx.credit - tx.debit);
    return { expected, difference: same(expected, tx.balance) ? 0 : round2(tx.balance - expected) };
  });

  const mismatches = [];
  let explainedByPrevious = false;
  differences.forEach((entry, i) => {
    if (!entry || entry.difference === 0) {
      explainedByPrevious = false;
      return;
    }
    // A wrong balance figure also breaks the next row; report it only once.
    if (explainedByPrevious) {
      explainedByPrevious = false;
      return;
    }
    const tx = transactions[i];
    const next = differences[i + 1];
    const diagnosis = diagnose(transactions, i, entry.difference, next ? next.difference : null);
    explainedByPrevious = diagnosis.cause === 'WRONG_BALANCE_FIGURE';
    mismatches.push({
      row: tx.row,
      date: tx.date,
      description: tx.description,
      debit: tx.debit,
      credit: tx.credit,
      expectedBalance: entry.expected,
      shownBalance: tx.balance,
      difference: entry.difference,
      ...diagnosis,
    });
  });

  return { checked: differences.filter(Boolean).length, mismatches };
}

// Decides whether every arithmetic mismatch could come from lines we could not
// read. A balance gap counts only when an unread line sits inside that gap.
// Row numbers run downwards when a newest-first file was reversed.
function explainedByUnreadLines({ transactions, rejected, openingBalance, stated, totals, unmatchedSummary }) {
  // An unread summary line holds no transaction, so it cannot explain a gap.
  const lines = rejected.filter((r) => !r.summary);
  if (!lines.length) return false;
  const first = transactions[0];
  const last = transactions[transactions.length - 1];
  const direction = first.row > last.row ? -1 : 1;
  const unreadBefore = (tx) => lines.some((r) => (tx.row - r.row) * direction > 0);
  const unreadAfter = (tx) => lines.some((r) => (r.row - tx.row) * direction > 0);
  const unreadBetween = (a, b) => lines.some((r) => (r.row - a.row) * (b.row - r.row) > 0);
  const openingKnown = openingBalance !== null && openingBalance !== undefined;

  // Every gap is examined, including those not listed separately as faults.
  let net = 0;
  let gaps = 0;
  for (let i = 0; i < transactions.length; i += 1) {
    const tx = transactions[i];
    const previous = i === 0 ? openingBalance : transactions[i - 1].balance;
    if (previous === null || previous === undefined) continue;
    const expected = round2(previous + tx.credit - tx.debit);
    if (same(expected, tx.balance)) continue;
    if (!(i === 0 ? unreadBefore(tx) : unreadBetween(transactions[i - 1], tx))) return false;
    net = round2(net + tx.balance - expected);
    gaps += 1;
  }

  const trailing = unreadAfter(last);
  if (stated.closingBalance !== null && !same(stated.closingBalance, last.balance)) {
    if (!trailing) return false;
    net = round2(net + stated.closingBalance - last.balance);
  }

  // At an end with no printed balance, the money on an unread line is unknown.
  const openEnd = (trailing && stated.closingBalance === null) || (!openingKnown && unreadBefore(first));
  const canHoldMoney = openEnd || gaps > 0 || trailing;

  // Unread lines can only make a calculated total too small, never too large.
  const missing = {};
  for (const side of ['totalCredit', 'totalDebit']) {
    missing[side] = stated[side] === null ? null : round2(stated[side] - totals[side]);
    if (missing[side] === null || same(missing[side], 0)) continue;
    if (!canHoldMoney || missing[side] < 0) return false;
  }
  if (!openEnd) {
    // What is missing from the totals must agree with what is missing from the balances.
    const { totalCredit: credit, totalDebit: debit } = missing;
    if (credit !== null && debit !== null) {
      if (!same(round2(credit - debit), net)) return false;
    } else if (credit !== null && credit < net - TOLERANCE) return false;
    else if (debit !== null && debit < -net - TOLERANCE) return false;
  }

  if (!unmatchedSummary) return true;
  return canHoldMoney && unmatchedSummary.figures.every(({ label, calculated }) => {
    if (label === 'closingBalance') return trailing;
    if (label === 'openingBalance') return unreadBefore(first);
    return unmatchedSummary.printed.some((v) => v >= calculated - TOLERANCE);
  });
}

// Gives each label the printed figure equal to our own calculation. One label
// and one figure left over is a clear mismatch; more than that cannot be
// assigned safely, so they are reported as unmatched.
function matchDetachedSummary({ labels, values }, calculated) {
  const remaining = [...values];
  const matched = {};
  const unmatched = [];
  for (const label of labels) {
    const at = remaining.findIndex((v) => same(v, calculated[label]));
    if (at >= 0) matched[label] = remaining.splice(at, 1)[0];
    else unmatched.push(label);
  }
  if (unmatched.length === 1) {
    matched[unmatched[0]] = remaining[0];
    return { matched, unmatched: null };
  }
  return {
    matched,
    unmatched: unmatched.length
      ? { figures: unmatched.map((label) => ({ label, calculated: calculated[label] })), printed: remaining }
      : null,
  };
}

function validateStatement({ transactions, rejected, openingBalance: givenOpening, stated: givenStated = {} }) {
  const first = transactions[0];
  let stated = givenStated;
  let openingBalance = givenOpening;
  let unmatchedSummary = null;
  if (givenStated.detached) {
    const credit = round2(sum(transactions.map((t) => t.credit)));
    const debit = round2(sum(transactions.map((t) => t.debit)));
    const result = matchDetachedSummary(givenStated.detached, {
      openingBalance: openingBalance ?? round2(first.balance - first.credit + first.debit),
      closingBalance: transactions[transactions.length - 1].balance,
      totalCredit: credit,
      totalDebit: debit,
    });
    stated = { ...givenStated, ...result.matched };
    openingBalance = openingBalance ?? result.matched.openingBalance ?? null;
    unmatchedSummary = result.unmatched;
  }
  const openingStated = openingBalance !== null && openingBalance !== undefined;
  // Without a stated opening balance the first row cannot be verified.
  const opening = openingStated ? openingBalance : round2(first.balance - first.credit + first.debit);

  const { checked, mismatches } = checkRunningBalance(transactions, openingStated ? openingBalance : null);

  const totalCredit = round2(sum(transactions.map((t) => t.credit)));
  const totalDebit = round2(sum(transactions.map((t) => t.debit)));
  const lastBalance = transactions[transactions.length - 1].balance;

  let outOfOrder = 0;
  let longestGapDays = 0;
  const outOfOrderRows = [];
  for (let i = 1; i < transactions.length; i += 1) {
    const gap = toDay(transactions[i].date) - toDay(transactions[i - 1].date);
    if (gap < 0) {
      outOfOrder += 1;
      outOfOrderRows.push(transactions[i].row);
    }
    longestGapDays = Math.max(longestGapDays, gap);
  }

  const totals = {
    openingBalance: opening,
    openingBalanceSource: openingStated ? 'stated' : 'derived from first row',
    totalCredit,
    totalDebit,
    calculatedClosingBalance: round2(opening + totalCredit - totalDebit),
    lastRowBalance: lastBalance,
  };
  const printed = {
    openingBalance: openingStated ? openingBalance : null,
    closingBalance: stated.closingBalance ?? null,
    totalCredit: stated.totalCredit ?? null,
    totalDebit: stated.totalDebit ?? null,
    periodStart: stated.periodStart ?? null,
    periodEnd: stated.periodEnd ?? null,
  };

  const total = transactions.length + rejected.length;
  return {
    totalRows: total,
    parsedRows: transactions.length,
    rejectedRows: rejected.length,
    balanceChecks: checked,
    mismatches,
    outOfOrder,
    outOfOrderRows,
    longestGapDays,
    totals,
    stated: printed,
    explainedByUnreadLines: explainedByUnreadLines({
      transactions, rejected, openingBalance: printed.openingBalance, stated: printed, totals, unmatchedSummary,
    }),
    summaryLayout: givenStated.detached ? 'figures printed apart from their labels' : 'figures beside their labels',
    unmatchedSummary,
  };
}

// The verification checklist, examined section by section. Each item ends as
// OK, DISCREPANCY or NA, and states the rule it was checked against.
// Severity of a discrepancy: HIGH = fault, MEDIUM = review, LOW = information.

const MAX_GAP_DAYS = 31;

const ok = (remarks) => ({ status: 'OK', remarks });
const na = (remarks) => ({ status: 'NA', remarks });
const bad = (remarks, rows = [], severity) => ({ status: 'DISCREPANCY', remarks, rows, severity });

// Compares a figure printed on the statement with the figure we calculated.
function matchFigure(label, printed, calculated, calculatedLabel) {
  if (printed === null) return na(`The statement prints no ${label}.`);
  const difference = round2(printed - calculated);
  return Math.abs(difference) <= TOLERANCE
    ? ok(`Printed ${label} ${formatMoney(printed)} matches ${calculatedLabel}.`)
    : bad(
      `Printed ${label} is ${formatMoney(printed)} but ${calculatedLabel} is ${formatMoney(calculated)} ` +
        `(difference ${formatMoney(difference)}).`,
    );
}

const SECTIONS = [
  {
    key: 'A',
    name: 'Reading completeness',
    items: [
      {
        sn: 'A001', parameter: 'Every transaction line was read', severity: 'MEDIUM',
        // Failing to read a line is our limitation, not proof of a fault in the statement.
        rule: 'A line that cannot be read means the statement is not fully verified. Above 20% the result is INCONCLUSIVE.',
        check: ({ validation: v }) => {
          if (!v.rejectedRows) return ok(`${v.parsedRows} of ${v.totalRows} lines read.`);
          return bad(`${v.rejectedRows} of ${v.totalRows} lines could not be read. See unreadLines.`);
        },
      },
      {
        sn: 'A002', parameter: 'Each entry is either a debit or a credit', severity: 'MEDIUM',
        rule: 'One line must not carry both a debit and a credit.',
        check: ({ transactions }) => {
          const both = transactions.filter((t) => t.debit !== 0 && t.credit !== 0);
          return both.length
            ? bad(`${both.length} line(s) carry both a debit and a credit.`, both.map((t) => t.row))
            : ok('No line carries both.');
        },
      },
      {
        sn: 'A003', parameter: 'An opening balance is printed', severity: 'LOW',
        rule: 'Without an opening balance the first transaction cannot be checked.',
        check: ({ validation: v }) =>
          v.stated.openingBalance === null
            ? na('No opening balance found; it was derived from the first row, which is therefore unchecked.')
            : ok(`Opening balance ${formatMoney(v.stated.openingBalance)}.`),
      },
    ],
  },
  {
    key: 'B',
    name: 'Arithmetic accuracy',
    items: [
      {
        sn: 'B001', parameter: 'Every running balance is correct', severity: 'HIGH',
        rule: 'Previous balance + credit - debit must equal the new balance, within 0.01.',
        check: ({ validation: v }) => {
          if (!v.balanceChecks) return na('There is no pair of balances to compare.');
          if (!v.mismatches.length) return ok(`All ${v.balanceChecks} balance calculations are correct.`);
          const x = v.mismatches[0];
          return bad(
            `${v.mismatches.length} fault(s) in ${v.balanceChecks} calculations. First: row ${x.row} (${x.date}), ` +
              `expected ${formatMoney(x.expectedBalance)}, shown ${formatMoney(x.shownBalance)}. See faults.`,
            v.mismatches.map((y) => y.row),
          );
        },
      },
      {
        sn: 'B002', parameter: 'Opening + credits - debits gives the closing balance', severity: 'HIGH',
        rule: 'The sum of all entries must lead from the opening balance to the closing balance.',
        check: ({ validation: v }) => {
          const t = v.totals;
          const printed = v.stated.closingBalance;
          const target = printed === null ? t.lastRowBalance : printed;
          const difference = round2(target - t.calculatedClosingBalance);
          const sum1 = `${formatMoney(t.openingBalance)} + ${formatMoney(t.totalCredit)} - ${formatMoney(t.totalDebit)} = ` +
            formatMoney(t.calculatedClosingBalance);
          return Math.abs(difference) <= TOLERANCE
            ? ok(`${sum1}.`)
            : bad(`${sum1}, but the statement closes at ${formatMoney(target)} (difference ${formatMoney(difference)}).`);
        },
      },
      {
        sn: 'B003', parameter: 'Printed closing balance matches the last row', severity: 'HIGH',
        rule: 'The closing balance in the summary must equal the balance after the last transaction.',
        check: ({ validation: v }) =>
          matchFigure('closing balance', v.stated.closingBalance, v.totals.lastRowBalance, 'the last row balance'),
      },
      {
        sn: 'B004', parameter: 'Printed total credits matches the entries', severity: 'HIGH',
        rule: 'The printed credit total must equal the sum of all credit entries.',
        check: ({ validation: v }) =>
          matchFigure('total credit', v.stated.totalCredit, v.totals.totalCredit, 'the sum of credit entries'),
      },
      {
        sn: 'B005', parameter: 'Printed total debits matches the entries', severity: 'HIGH',
        rule: 'The printed debit total must equal the sum of all debit entries.',
        check: ({ validation: v }) =>
          matchFigure('total debit', v.stated.totalDebit, v.totals.totalDebit, 'the sum of debit entries'),
      },
      {
        sn: 'B006', parameter: 'No printed summary figure is left unexplained', severity: 'HIGH',
        rule: 'Every figure in the printed summary block must be explained by the transactions.',
        check: ({ validation: v }) => {
          const x = v.unmatchedSummary;
          if (!x) return ok('No unexplained summary figure.');
          return bad(
            `${x.figures.map((f) => `${f.label} should be ${formatMoney(f.calculated)}`).join('; ')}. ` +
              `Unexplained printed figures: ${x.printed.map(formatMoney).join(', ')}.`,
          );
        },
      },
    ],
  },
  {
    key: 'C',
    name: 'Dates and sequence',
    items: [
      {
        sn: 'C001', parameter: 'Transactions are in date order', severity: 'MEDIUM',
        rule: 'Dates must not go backwards within the statement.',
        check: ({ validation: v }) =>
          v.outOfOrder ? bad(`${v.outOfOrder} date(s) go backwards.`, v.outOfOrderRows) : ok('Dates are in order.'),
      },
      {
        sn: 'C002', parameter: 'All dates fall inside the printed period', severity: 'MEDIUM',
        rule: 'Every transaction must belong to the statement period.',
        check: ({ validation: v, transactions }) => {
          const { periodStart: from, periodEnd: to } = v.stated;
          if (!from) return na('The statement prints no period.');
          const outside = transactions.filter((t) => t.date < from || t.date > to);
          return outside.length
            ? bad(`${outside.length} entry(ies) outside ${from} to ${to}.`, outside.map((t) => t.row))
            : ok(`All entries are within ${from} to ${to}.`);
        },
      },
      {
        sn: 'C003', parameter: 'No transaction is dated in the future', severity: 'HIGH',
        rule: 'No transaction may be dated after the verification date.',
        check: ({ transactions, asOfDate }) => {
          const future = transactions.filter((t) => t.date > asOfDate);
          return future.length
            ? bad(`${future.length} entry(ies) dated after ${asOfDate}.`, future.map((t) => t.row))
            : ok(`No entry after ${asOfDate}.`);
        },
      },
      {
        sn: 'C004', parameter: 'No long silent period', severity: 'LOW',
        rule: `A gap of more than ${MAX_GAP_DAYS} days can mean missing pages.`,
        check: ({ validation: v, transactions }) => {
          const after = transactions.filter(
            (t, i) => i > 0 && toDay(t.date) - toDay(transactions[i - 1].date) > MAX_GAP_DAYS,
          );
          return after.length
            ? bad(`Longest gap is ${v.longestGapDays} days.`, after.map((t) => t.row))
            : ok(`Longest gap is ${v.longestGapDays} day(s).`);
        },
      },
    ],
  },
  {
    key: 'D',
    name: 'Duplicates and unusual entries',
    items: [
      {
        sn: 'D001', parameter: 'No transaction reference is reused', severity: 'MEDIUM',
        rule: 'One reference must not appear twice with the same amount.',
        check: ({ transactions, detections: d }) => {
          if (!transactions.some((t) => t.reference)) return na('The statement has no reference column.');
          return d.duplicateReferences.length
            ? bad(`Reused: ${d.duplicateReferences.map((r) => r.reference).slice(0, 5).join(', ')}.`,
              d.duplicateReferences.flatMap((r) => r.rows))
            : ok('No reference is reused.');
        },
      },
      {
        sn: 'D002', parameter: 'No identical same-day entries', severity: 'LOW',
        rule: 'Entries without a reference that match on date, text and amount need a look.',
        check: ({ detections: d }) =>
          d.repeatedEntryRows.length
            ? bad(`${d.repeatedEntryRows.length} entries look identical. These can be genuine.`, d.repeatedEntryRows)
            : ok('No identical entries.'),
      },
      {
        sn: 'D003', parameter: 'No amount far outside the usual range', severity: 'LOW',
        rule: 'An amount over 10 times the typical credit or debit is pointed out.',
        check: ({ detections: d }) => {
          if (d.outlierRows === null) return na('Too few entries to know what is usual.');
          return d.outlierRows.length
            ? bad(`${d.outlierRows.length} unusually large entry(ies).`, d.outlierRows)
            : ok('No unusual amount.');
        },
      },
      {
        sn: 'D004', parameter: 'Account is not overdrawn', severity: 'LOW',
        rule: 'The balance should not fall below zero.',
        check: ({ transactions }) => {
          const negative = transactions.filter((t) => t.balance < 0);
          return negative.length
            ? bad(`Balance is below zero on ${negative.length} row(s).`, negative.map((t) => t.row))
            : ok('The balance never goes below zero.');
        },
      },
      {
        sn: 'D005', parameter: 'No bounced or returned payments', severity: 'MEDIUM',
        rule: 'One returned payment is information; two or more need review.',
        check: ({ detections: d }) => {
          const count = d.bounceRows.length;
          return count
            ? bad(`${count} bounce-related entry(ies).`, d.bounceRows, count > 1 ? 'MEDIUM' : 'LOW')
            : ok('No returned payment.');
        },
      },
      {
        sn: 'D006', parameter: 'Reversal entries are accounted for', severity: 'LOW',
        rule: 'A negative amount in a debit or credit column is a reversal. It keeps its sign in every calculation.',
        check: ({ transactions }) => {
          const reversals = transactions.filter((t) => t.debit < 0 || t.credit < 0);
          return {
            ...ok(reversals.length
              ? `${reversals.length} reversal entry(ies) with negative amounts, included with their sign.`
              : 'No negative amounts.'),
            rows: reversals.map((t) => t.row),
          };
        },
      },
    ],
  },
  {
    key: 'E',
    name: 'Suspicious patterns',
    items: [
      {
        sn: 'E001', parameter: 'No unusual large deposit just before the end', severity: 'MEDIUM',
        rule: 'A deposit in the last 14 days that is at least half of monthly inflow and 4 times the typical credit must be explained.',
        check: ({ detections: d }) => {
          if (d.lateDeposits === null) return na('Not enough earlier history to compare with.');
          return d.lateDeposits.length
            ? bad(`${d.lateDeposits.length} deposit(s) totalling ${formatMoney(round2(sum(d.lateDeposits.map((x) => x.amount))))}. Verify the source.`,
              d.lateDeposits.map((x) => x.row))
            : ok('No unusual late deposit.');
        },
      },
      {
        sn: 'E002', parameter: 'No money moved in and straight out', severity: 'MEDIUM',
        rule: 'A large credit that leaves within 3 days at nearly the same amount must be explained.',
        check: ({ detections: d }) =>
          d.roundTrips.length
            ? bad(`${d.roundTrips.length} round trip(s) found.`, d.roundTrips.flatMap((p) => [p.creditRow, p.debitRow]))
            : ok('No round trip found.'),
      },
      {
        sn: 'E003', parameter: 'File was not submitted for another account holder', severity: 'HIGH',
        rule: 'The same statement file must not belong to two different people.',
        check: ({ accountHolder, duplicateOf }) => {
          if (!accountHolder) return na('No account_holder was sent, so submissions cannot be compared.');
          return duplicateOf
            // The other submission's reference belongs to another caller, so it is not shown.
            ? bad('This exact file was submitted earlier for a different account holder. ' +
              'Operators can find that submission in the audit log by the file hash.')
            : ok('No earlier submission for a different account holder is on record.');
        },
      },
    ],
  },
];

function runChecklist(context) {
  return SECTIONS.map((section) => ({
    key: section.key,
    name: section.name,
    items: section.items.map((item) => {
      const outcome = item.check(context);
      return {
        sn: item.sn,
        parameter: item.parameter,
        rule: item.rule,
        status: outcome.status,
        severity: outcome.status === 'DISCREPANCY' ? outcome.severity || item.severity : null,
        remarks: outcome.remarks,
        rows: (outcome.rows || []).slice(0, 25),
      };
    }),
  }));
}

function summarizeChecklist(sections) {
  const items = sections.flatMap((s) => s.items.map((i) => ({ section: s.key, ...i })));
  const count = (status) => items.filter((i) => i.status === status).length;
  const rank = { HIGH: 0, MEDIUM: 1, LOW: 2 };
  return {
    summary: {
      totalChecks: items.length,
      ok: count('OK'),
      discrepancy: count('DISCREPANCY'),
      notApplicable: count('NA'),
    },
    discrepancies: items
      .filter((i) => i.status === 'DISCREPANCY')
      .sort((a, b) => rank[a.severity] - rank[b.severity])
      .map(({ sn, section, parameter, severity, remarks, rows }) => ({ sn, section, parameter, severity, remarks, rows })),
  };
}

// Decides the verdict and builds the JSON that the API returns.

// When most of what we read does not add up, or much of it could not be read,
// the likelier explanation is a layout we do not understand. Say so instead of
// accusing the statement.
function readingIsUnreliable(v) {
  if (!v.balanceChecks) return true;
  const mostFail = v.mismatches.length >= 3 && v.mismatches.length / v.balanceChecks > 0.5;
  return mostFail || v.rejectedRows / v.totalRows > 0.2;
}

function decide(validation, discrepancies) {
  const arithmeticFault = discrepancies.some((d) => d.section === 'B');
  const has = (severity) => discrepancies.some((d) => d.severity === severity);

  if (readingIsUnreliable(validation)) {
    return {
      verdict: 'INCONCLUSIVE',
      accountsCorrect: null,
      headline: 'The statement could not be read reliably. This is not evidence of a fault; check the file layout.',
    };
  }

  // Gaps that sit where lines could not be read are our limitation, not a fault.
  // Other serious findings, outside the arithmetic, still count.
  const unreadGap = arithmeticFault && validation.explainedByUnreadLines;
  if (unreadGap && !discrepancies.some((d) => d.severity === 'HIGH' && d.section !== 'B')) {
    return {
      verdict: 'REVIEW_REQUIRED',
      accountsCorrect: null,
      headline: 'Some lines could not be read, and the figures do not add up around them. The accounts are not verified.',
    };
  }

  let accountsCorrect = !arithmeticFault;
  if (validation.rejectedRows && (accountsCorrect || unreadGap)) accountsCorrect = null;

  if (has('HIGH')) {
    const rows = validation.mismatches.map((m) => m.row);
    let headline = 'A serious fault was found. See discrepancies.';
    if (arithmeticFault && !unreadGap) {
      headline = rows.length
        ? `The accounts do not add up: ${rows.length} fault(s), first at row ${rows[0]}.`
        : 'The printed summary figures do not match the transactions.';
    }
    return { verdict: 'FAULTS_FOUND', accountsCorrect, headline };
  }
  if (has('MEDIUM')) {
    return {
      verdict: 'REVIEW_REQUIRED',
      accountsCorrect,
      headline: accountsCorrect
        ? 'The arithmetic is correct, but some items need a human to check them.'
        : 'Some lines could not be read, so the accounts are only partly verified.',
    };
  }
  return { verdict: 'VERIFIED', accountsCorrect, headline: 'The accounts add up and no item needs review.' };
}

function assembleResponse({ intake, validation, analysis, sections, rejected, aiReview }) {
  const { summary, discrepancies } = summarizeChecklist(sections);
  const result = decide(validation, discrepancies);
  const ai = aiReview || { requested: false, status: 'NOT_REQUESTED', concerns: [], failedSections: [] };
  const { totals, stated, mismatches } = validation;

  const manualHandling = discrepancies
    .filter((d) => d.severity !== 'LOW')
    .map((d) => `${d.sn} (${d.severity}): ${d.parameter}`);
  if (result.verdict === 'INCONCLUSIVE') manualHandling.unshift('Statement layout could not be read reliably.');
  if (ai.status === 'UNAVAILABLE') manualHandling.push('AI review was requested but did not return a usable answer.');
  if (ai.status === 'PARTIAL') manualHandling.push(`AI review is missing for section(s) ${ai.failedSections.join(', ')}.`);
  if (ai.concerns.length) manualHandling.push(`AI review raised ${ai.concerns.length} concern(s).`);

  const closingTarget = stated.closingBalance === null ? totals.lastRowBalance : stated.closingBalance;

  return {
    success: true,
    reference: intake.reference,
    accountHolder: intake.accountHolder,
    statement: {
      fileName: intake.fileName,
      fileType: intake.fileType,
      sha256: intake.sha256,
      periodStart: analysis.periodStart,
      periodEnd: analysis.periodEnd,
      transactionCount: analysis.transactionCount,
      verifiedAsOf: intake.asOfDate,
    },
    result,
    reconciliation: {
      openingBalance: totals.openingBalance,
      openingBalanceSource: totals.openingBalanceSource,
      totalCredit: totals.totalCredit,
      totalDebit: totals.totalDebit,
      calculatedClosingBalance: totals.calculatedClosingBalance,
      lastRowBalance: totals.lastRowBalance,
      printedClosingBalance: stated.closingBalance,
      printedTotalCredit: stated.totalCredit,
      printedTotalDebit: stated.totalDebit,
      unexplainedDifference: round2(closingTarget - totals.calculatedClosingBalance),
      balanceCalculationsChecked: validation.balanceChecks,
    },
    faults: mismatches.slice(0, 100).map((m) => ({
      ...m,
      summary:
        `Row ${m.row}, ${m.date}: expected ${formatMoney(m.expectedBalance)} but the statement shows ` +
        `${formatMoney(m.shownBalance)}.`,
    })),
    faultCount: mismatches.length,
    verification: { summary, discrepancies, sections },
    analysis,
    unreadLines: rejected.slice(0, 50).map(({ row, reason }) => ({ row, reason })),
    aiReview: ai,
    processing: {
      straightThrough: result.verdict === 'VERIFIED' && manualHandling.length === 0,
      manualHandling,
    },
  };
}

// --- node ---
const data = $('Run Checklist').first(0).json;
const ai = $('Merge AI Review').isExecuted ? $('Merge AI Review').first(0).json : null;
const response = assembleResponse({
  intake: data.intake, validation: data.validation, analysis: data.analysis,
  sections: ai ? ai.sections : data.sections, rejected: data.rejected,
  aiReview: ai ? ai.aiReview : undefined,
});
return [{ json: { httpStatus: 200, response, transactions: data.transactions } }];

/**
 * n8n node  : Build Error Response
 * Author    : Hasan Gaffar
 * Project   : n8n Bank Statement Verifier
 * Input from: Request OK?, Fingerprint File, Reattach File, Extract CSV, Extract Excel, Extract PDF, PDF Has Text?, Parse Transactions, Parsed OK?, Check Arithmetic, Categorize Transactions, Detect Patterns, Analyse Account, Find Earlier Submissions, Run Checklist, Build Haiku Requests, Route Models, Merge AI Review, Assemble Response
 * Output to : Prepare Audit Record
 * Source    : generated from src/ by scripts/build-workflows.js
 */

const request = $('Check Request').first().json;
const item = $input.first().json;
const from = $prevNode.name;
let httpStatus;
let error;
let failedNode = '';
let errorDetail = '';
if (!request.valid) ({ httpStatus, error } = request);
else if (item.httpStatus && item.error?.code) ({ httpStatus, error } = item);
else if (from === 'PDF Has Text?') {
  httpStatus = 422;
  error = { code: 'OCR_REQUIRED', message: 'The PDF has no readable text (scanned image). OCR is not included.' };
} else if (from.startsWith('Extract ')) {
  httpStatus = 422;
  error = { code: 'STATEMENT_UNREADABLE', message: 'The file could not be read. It may be damaged or password protected.' };
  errorDetail = String(item.error?.message || item.error || '').slice(0, 1000);
} else {
  // A processing node crashed. The caller gets no internal detail; the audit log does.
  httpStatus = 500;
  error = { code: 'UNEXPECTED_ERROR', message: 'Processing failed unexpectedly. Quote the reference to find it in the audit log.' };
  failedNode = from;
  errorDetail = String(item.error?.message || item.error || 'Unknown error').slice(0, 1000);
}
const reference = request.reference || 'REQ-' + $execution.id;
return [{ json: { httpStatus, response: { success: false, reference, error }, failedNode, errorDetail } }];

/**
 * n8n node  : Prepare Error Record
 * Author    : Hasan Gaffar
 * Project   : n8n Bank Statement Verifier
 * Input from: Ensure Audit Table For Error
 * Output to : Save Error Record
 * Source    : generated from src/ by scripts/build-workflows.js
 */

const failure = $('On Unexpected Error').first().json;
const execution = failure.execution || {};
const message = String(execution.error?.message || failure.trigger?.error?.message || 'Unknown error').slice(0, 1000);
const executionId = String(execution.id || '');
const reference = 'ERR-' + (executionId || Date.now());
return [{ json: {
  received_at: new Date().toISOString(),
  reference,
  account_holder: '', file_name: '', file_type: '', sha256: '',
  http_status: 500,
  success: false,
  verdict: '', accounts_correct: 'unknown', transaction_count: 0, fault_count: 0, discrepancy_ids: '',
  error_code: 'UNEXPECTED_ERROR',
  ai_status: '', ai_route: '', ai_models: '', ai_input_tokens: 0, ai_output_tokens: 0, ai_cost_usd: 0,
  duration_ms: 0,
  execution_id: executionId,
  response_json: JSON.stringify({ success: false, reference, error: { code: 'UNEXPECTED_ERROR', message } }),
  transactions_json: '[]',
  error_message: message,
  failed_node: execution.lastNodeExecuted || '',
  ai_duration_ms: 0, ai_errors: '', ai_usage_json: '[]',
} }];
